import { Alert, Button, Field, FieldError, FieldLabel, PasswordInput, cn } from '@gntik-ai/ui';
import { CircleCheck } from '@gntik-ai/icons';
import { useState, type ReactNode } from 'react';
import { AuthHeader, authFormClass, useAsyncSubmit } from '../shared';

export interface ResetPasswordFormProps {
  /** Saves the new password. A returned promise shows the loading state; a rejection shows in the alert. */
  onSubmit?: (password: string) => void | Promise<void>;
  error?: string | null;
  minPasswordLength?: number;
  /** Called from the success state ("Continue to sign in"). */
  onContinue?: () => void;
  eyebrow?: ReactNode;
  className?: string;
}

/** New password + confirmation with length and mismatch validation, then a success state. */
export function ResetPasswordForm({
  onSubmit,
  error: errorProp,
  minPasswordLength = 8,
  onContinue,
  eyebrow = 'Account recovery',
  className,
}: ResetPasswordFormProps) {
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [confirmTouched, setConfirmTouched] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [done, setDone] = useState(false);
  const { loading, error, run } = useAsyncSubmit('Your password could not be updated.');
  const alert = errorProp ?? error;
  const tooShort = password.length < minPasswordLength;
  const mismatch = confirm !== password;
  const passwordInvalid = submitted && tooShort;
  const confirmInvalid = (submitted || (confirmTouched && confirm !== '')) && mismatch;

  if (done) {
    return (
      <div className={cn(authFormClass, className)}>
        <span className="mb-5 grid size-11 place-items-center rounded-xl bg-success/14 text-success-chip-text">
          <CircleCheck size={20} aria-hidden />
        </span>
        <AuthHeader
          eyebrow={eyebrow}
          title="Password updated"
          description="You can now sign in with your new password. Other sessions were signed out."
        />
        <div role="status" className="sr-only">
          Password updated.
        </div>
        <Button size="lg" className="w-full" onClick={onContinue}>
          Continue to sign in
        </Button>
      </div>
    );
  }

  return (
    <div className={cn(authFormClass, className)}>
      <AuthHeader
        eyebrow={eyebrow}
        title="Set a new password"
        description={`Use at least ${minPasswordLength} characters. Avoid passwords you use elsewhere.`}
      />
      <form
        noValidate
        aria-label="Set a new password"
        className="flex flex-col gap-4"
        onSubmit={(e) => {
          e.preventDefault();
          setSubmitted(true);
          if (tooShort || mismatch) return;
          void run(() => onSubmit?.(password)).then((ok) => ok && setDone(true));
        }}
      >
        {alert && <Alert tone="destructive" description={alert} />}
        <Field invalid={passwordInvalid}>
          <FieldLabel>New password</FieldLabel>
          <PasswordInput showStrength value={password} onValueChange={setPassword} required />
          <FieldError match={passwordInvalid}>Use at least {minPasswordLength} characters.</FieldError>
        </Field>
        <Field invalid={confirmInvalid}>
          <FieldLabel>Confirm password</FieldLabel>
          <PasswordInput
            autoComplete="new-password"
            value={confirm}
            onValueChange={setConfirm}
            onBlur={() => setConfirmTouched(true)}
            required
          />
          <FieldError match={confirmInvalid}>Passwords don't match.</FieldError>
        </Field>
        <Button type="submit" size="lg" loading={loading} className="mt-2 w-full">
          Update password
        </Button>
      </form>
    </div>
  );
}

import { cn } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';

export interface AuthHeaderProps {
  eyebrow?: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  /** Defaults to h1. `null` omits the title heading. */
  headingLevel?: 'h1' | 'h2' | 'h3' | null;
  className?: string;
}

/** Eyebrow + title + supporting line used at the top of every auth form. */
export function AuthHeader({ eyebrow, title, description, headingLevel: Heading = 'h1', className }: AuthHeaderProps) {
  return (
    <div className={cn('mb-6', className)}>
      {eyebrow != null && (
        <p className="mb-2.5 font-mono text-[11px] tracking-[0.2em] text-primary-text uppercase">{eyebrow}</p>
      )}
      {Heading != null && title != null && (
        <Heading className="text-[24px] font-semibold tracking-tight text-balance text-foreground sm:text-[27px]">
          {title}
        </Heading>
      )}
      {description != null && (
        <p className="mt-2 text-[14px] leading-relaxed text-pretty text-muted-foreground">{description}</p>
      )}
    </div>
  );
}

/** Horizontal rule with a centred caption ("Or continue with"). */
export function AuthDivider({ children }: { children: ReactNode }) {
  return (
    <div className="my-6 flex items-center gap-3" role="presentation">
      <span className="h-px flex-1 bg-border" />
      <span className="font-mono text-[10.5px] font-semibold tracking-[0.2em] text-muted-foreground uppercase">
        {children}
      </span>
      <span className="h-px flex-1 bg-border" />
    </div>
  );
}

export const authFormClass = 'w-full max-w-[392px]';

/** Loading + error state around an async submit handler. A rejection's message becomes the error. */
export function useAsyncSubmit(fallbackError = 'Something went wrong. Try again.') {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const run = async (fn: () => void | Promise<void>) => {
    setError(null);
    setLoading(true);
    try {
      await fn();
      setLoading(false);
      return true;
    } catch (e) {
      setLoading(false);
      setError(e instanceof Error ? e.message : fallbackError);
      return false;
    }
  };
  return { loading, error, setError, run };
}

export const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Email by default; text mode supports a username or username-or-email identifier. */
export interface AuthIdentifierConfig {
  type?: 'email' | 'text';
  autoComplete?: string;
  label?: ReactNode;
  help?: ReactNode;
  /** Optional stable id for the FieldDescription. Otherwise Base UI generates it. */
  helpId?: string;
  placeholder?: string;
  minLength?: number;
  maxLength?: number;
}

/** Kit-owned inline validation; consumers supply copy rather than running a second validator. */
export interface AuthValidationMessages {
  identifierRequired?: string;
  identifierInvalid?: string;
  identifierTooShort?: string;
  passwordRequired?: string;
}

/** Server errors use only these props plus the form's error alert; inline validation stays in the kit. */
export interface AuthFormAccessibilityProps {
  fieldInvalid?: { identifier?: boolean; password?: boolean };
  /** Id of the server alert (or an external feedback element), appended to flagged inputs. */
  feedbackId?: string;
  /** Describes the form itself; does not replace the per-field feedback association. */
  'aria-describedby'?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
}

export function authIdentifierError(value: string, config?: AuthIdentifierConfig, messages?: AuthValidationMessages) {
  const trimmed = value.trim();
  const fallback = config?.type === 'text' ? 'Enter a valid identifier.' : 'Enter a valid email address.';
  if (!trimmed) return messages?.identifierRequired ?? fallback;
  if (config?.minLength !== undefined && trimmed.length < config.minLength)
    return messages?.identifierTooShort ?? messages?.identifierInvalid ?? fallback;
  if (
    ((config?.type ?? 'email') === 'email' && !EMAIL_RE.test(trimmed)) ||
    (config?.maxLength !== undefined && trimmed.length > config.maxLength)
  )
    return messages?.identifierInvalid ?? fallback;
  return null;
}

/** Ordered text/email fields collected before the sign-up password. Ids must be unique. */
export interface AuthSignUpField {
  id: string;
  label: string;
  placeholder?: string;
  help?: ReactNode;
  required?: boolean;
  type?: 'text' | 'email';
  autoComplete?: string;
  /** Consumer copy for kit-owned validation. */
  messages?: { required?: string; invalid?: string };
}

export function authSignUpFieldError(value: string, field: AuthSignUpField) {
  const trimmed = value.trim();
  if (!trimmed) return field.required ? (field.messages?.required ?? `Enter ${field.label}.`) : null;
  if (field.type === 'email' && !EMAIL_RE.test(trimmed))
    return field.messages?.invalid ?? 'Enter a valid email address.';
  return null;
}

/** Consumer-owned copy and optional action when account creation is unavailable. */
export interface AuthUnavailableState {
  title: ReactNode;
  message: ReactNode;
  action?: ReactNode;
}

/** Kit-owned sign-up validation with consumer-owned copy. */
export interface AuthSignUpValidationMessages {
  passwordTooShort?: (minimum: number) => string;
  termsRequired?: string;
}
